import AVFoundation
import Foundation

/// A one-second 32×32 black source gives the compositor a continuous clock,
/// including pure-image projects and gaps. It is generated by system frameworks.
internal actor CarrierCache {
    static let shared = CarrierCache()
    private var task: Task<URL, Error>?
    private var cachedSilence: URL?
    func silenceURL() throws -> URL {
        if let cachedSilence { return cachedSilence }
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("IndependentEditor-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let url = directory.appendingPathComponent("silence-\(UUID().uuidString).wav")
        var data = Data()
        func text(_ value: String) { data.append(contentsOf: value.utf8) }
        func u16(_ value: UInt16) { var little = value.littleEndian; withUnsafeBytes(of: &little) { data.append(contentsOf: $0) } }
        func u32(_ value: UInt32) { var little = value.littleEndian; withUnsafeBytes(of: &little) { data.append(contentsOf: $0) } }
        text("RIFF"); u32(36 + 192000); text("WAVEfmt "); u32(16); u16(1); u16(2)
        u32(48000); u32(192000); u16(4); u16(16); text("data"); u32(192000)
        data.append(Data(count: 192000))
        try data.write(to: url, options: .atomic)
        cachedSilence = url
        return url
    }
    func url() async throws -> URL {
        if let task { return try await task.value }
        let newTask = Task.detached(priority: .userInitiated) { try await Self.make() }
        task = newTask
        do { return try await newTask.value }
        catch { task = nil; throw error }
    }
    private static func make() async throws -> URL {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("IndependentEditor-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let url = directory.appendingPathComponent("carrier-\(UUID().uuidString).mp4")
        let writer = try AVAssetWriter(outputURL: url, fileType: .mp4)
        let input = AVAssetWriterInput(mediaType: .video, outputSettings: [
            AVVideoCodecKey: AVVideoCodecType.h264,
            AVVideoWidthKey: 32, AVVideoHeightKey: 32,
            AVVideoCompressionPropertiesKey: [AVVideoAverageBitRateKey: 16000, AVVideoExpectedSourceFrameRateKey: 30, AVVideoMaxKeyFrameIntervalKey: 30]
        ])
        input.expectsMediaDataInRealTime = false
        let adaptor = AVAssetWriterInputPixelBufferAdaptor(assetWriterInput: input, sourcePixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferWidthKey as String: 32, kCVPixelBufferHeightKey as String: 32,
            kCVPixelBufferCGImageCompatibilityKey as String: true
        ])
        guard writer.canAdd(input) else { throw MediaEngineError.render("无法创建内部画面时钟") }
        writer.add(input)
        guard writer.startWriting() else { throw writer.error ?? MediaEngineError.render("内部画面时钟启动失败") }
        writer.startSession(atSourceTime: .zero)
        do {
            guard let pool = adaptor.pixelBufferPool else { throw MediaEngineError.render("内部画面缓冲池创建失败") }
            var buffer: CVPixelBuffer?
            guard CVPixelBufferPoolCreatePixelBuffer(nil, pool, &buffer) == kCVReturnSuccess, let buffer else { throw MediaEngineError.render("内部画面缓冲创建失败") }
            CVPixelBufferLockBaseAddress(buffer, [])
            let base = CVPixelBufferGetBaseAddress(buffer)!.assumingMemoryBound(to: UInt8.self)
            let stride = CVPixelBufferGetBytesPerRow(buffer)
            for y in 0..<32 { for x in 0..<32 {
                let offset = y * stride + x * 4
                base[offset] = 0; base[offset + 1] = 0; base[offset + 2] = 0; base[offset + 3] = 255
            } }
            CVPixelBufferUnlockBaseAddress(buffer, [])
            for frame in 0..<30 {
                while !input.isReadyForMoreMediaData {
                    try Task.checkCancellation()
                    if writer.status == .failed { throw writer.error ?? MediaEngineError.render("内部时钟写入失败") }
                    try await Task.sleep(nanoseconds: 1_000_000)
                }
                guard adaptor.append(buffer, withPresentationTime: CMTime(value: Int64(frame), timescale: 30)) else { throw writer.error ?? MediaEngineError.render("内部时钟写入失败") }
            }
            writer.endSession(atSourceTime: CMTime(value: 1, timescale: 1))
            input.markAsFinished()
            await writer.finishWriting()
            guard writer.status == .completed else { throw writer.error ?? MediaEngineError.render("内部时钟保存失败") }
            return url
        } catch {
            writer.cancelWriting()
            try? FileManager.default.removeItem(at: url)
            throw error
        }
    }
}
